from pyspark.accumulators import AccumulatorParam

class DictCounterAccumulator(AccumulatorParam):
    def zero(self, value):
        return {}
    def addInPlace(self, val1, val2):
        for k, v in val2.items():
            val1[k] = val1.get(k, 0) + v
        return val1

# Register with SparkContext
audit_acc = spark.sparkContext.accumulator({}, DictCounterAccumulator())

def audit_row_inline(row):
    local_metrics = {}
    if row.user_id is None:
        local_metrics["missing_user_id"] = 1
    if row.amount < 0:
        local_metrics["negative_amount"] = 1
    if local_metrics:
        audit_acc.add(local_metrics)
    return row

# Transforms and audits simultaneously during physical write action
valid_df = raw_df.rdd.map(audit_row_inline).toDF(raw_df.schema)
valid_df.write.format("delta").mode("append").save(target_path)

# Driver reads aggregated telemetry with ZERO extra compute passes
print("Audit Telemetry:", audit_acc.value)

