from airflow.decorators import dag, task
from datetime import datetime

@dag(schedule="@daily", start_date=datetime(2026, 1, 1), catchup=False)
def pipeline_clean():

    @task
    def fetch_active_tenants():
        # DB connection happens ONLY when worker executes the task!
        from airflow.providers.postgres.hooks.postgres import PostgresHook
        hook = PostgresHook(postgres_conn_id="prod_postgres")
        return hook.get_records("SELECT id FROM tenants")

    @task
    def process_tenant(tenant_id):
        print(f"Processing tenant {tenant_id}")

    tenants = fetch_active_tenants()
    process_tenant.expand(tenant_id=tenants)

pipeline_clean()

